INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 22, 'theory', 'Quiz: scheduler, migration, HA');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 0, 'How does the oVirt scheduler choose a host in a cluster?', '["It ranks weights first and then applies filters", "Filters drop unfit hosts, and among the rest the best weighted sum of ranks wins", "The host with the most cores is chosen", "The modules vote and the majority wins"]', 1, 'Filters are hard: they strike out hosts where the start is impossible. Weights are soft: each module ranks the hosts, the ranks are multiplied by the policy factors and summed, and the host with the best total wins.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 1, 'A host has 64 GiB of memory, the cluster memory optimization is 150%, running VMs take 70 GiB, and we ignore the reserve. Will another 30 GiB VM fit?', '["Yes, 64 GiB of physical memory is more than 30", "Yes, but only if ballooning is enabled", "No, the optimization applies only to desktop VMs", "No, scheduling memory is 96 GiB, 26 GiB remain, which is too little"]', 3, 'Scheduling memory is 64 × 1.5 = 96 GiB. Minus the 70 GiB already promised leaves 26 GiB, while the new machine needs 30 GiB, so the memory filter drops the host.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 2, 'What is the main risk of the post-copy migration policy?', '["A network break between hosts after the switch can lose the running VM", "The migration never converges", "The downtime always exceeds a minute", "A VM with a lot of memory cannot be migrated"]', 0, 'In post-copy the VM already runs on the destination while some pages still sit on the source. If the link breaks, the missing pages cannot be fetched and the instance is lost. In return, convergence is guaranteed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 3, 'What does a VM lease on a storage domain give?', '["It speeds up migration", "It allows exceeding the memory limit", "It guarantees the VM is not running in two places and lets it be restarted safely without fencing the host", "It replaces backups"]', 2, 'The lease is held by the host where the VM runs. While it is alive, a second copy cannot start; when the host has gone and the lease has expired, the engine can start the machine elsewhere without waiting for fencing.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 22, 4, 'Which resilience policy should you pick so that only critical VMs are migrated when a host becomes non-operational?', '["Migrate all VMs", "Migrate only highly available VMs", "Do not migrate VMs", "Turn on the none policy"]', 1, 'The policy "migrate only highly available" moves VMs with the high-availability flag and leaves the rest on the host. The none policy belongs to the scheduler, not to resilience.');
